222	import { HttpStatus, Injectable } from '@nestjs/common';
223	import { InjectRepository } from '@nestjs/typeorm';
224	import { BookingEntity, IdempotencyKeyEntity } from '@roombook/backend-common';
225	import { ConfirmationStatusEnum } from '@roombook/contract';
226	import { DataSource, EntityManager, Repository } from 'typeorm';
227	import { BookingMapper } from './booking.mapper';
228	import { CreateBookingCommand } from './dto/create-booking.command';
229	import { IdempotentCreateOutcome, IdempotentCreateOutcomeKindEnum } from './dto/idempotent-create-outcome';
230	
231	type AdvisoryLockRow = { locked: boolean };
232	
233	const TRY_KEY_LOCK_SQL = 'SELECT pg_try_advisory_xact_lock(hashtextextended($1, 0)) AS "locked"';
234	
235	@Injectable()
236	export class IdempotentBookingRepository {
237	  constructor(
238	    private readonly dataSource: DataSource,
239	    @InjectRepository(IdempotencyKeyEntity) private readonly keys: Repository<IdempotencyKeyEntity>,
240	  ) {}
241	
242	  findByKey(key: string): Promise<IdempotencyKeyEntity | null> {
243	    return this.keys.findOneBy({ key });
244	  }
245	
246	  create(command: CreateBookingCommand): Promise<IdempotentCreateOutcome> {
247	    return this.dataSource.transaction((manager) => this.createLocked(manager, command));
248	  }
249	
250	  private async createLocked(manager: EntityManager, command: CreateBookingCommand): Promise<IdempotentCreateOutcome> {
251	    const { idempotencyKey: key, requestFingerprint, ...values } = command;
252	    const [lock] = await manager.query<AdvisoryLockRow[]>(TRY_KEY_LOCK_SQL, [key]);
253	    if (!lock.locked) {
254	      return { kind: IdempotentCreateOutcomeKindEnum.IN_PROGRESS };
255	    }
256	    const storedKey = await manager.findOneBy(IdempotencyKeyEntity, { key });
257	    if (storedKey) {
258	      return { kind: IdempotentCreateOutcomeKindEnum.EXISTING, storedKey };
259	    }
260	    const entity = manager.create(BookingEntity, {
261	      ...values,
262	      confirmationStatus: ConfirmationStatusEnum.PENDING,
263	      confirmationAttempts: 0,
264	    });
265	    const booking = BookingMapper.toDto(await manager.save(BookingEntity, entity));
266	    await manager.insert(IdempotencyKeyEntity, {
267	      key,
268	      requestFingerprint,
269	      responseStatus: HttpStatus.CREATED,
270	      responseBody: booking,
271	    });
272	    return { kind: IdempotentCreateOutcomeKindEnum.CREATED, booking };
273	  }
274	}
