404	import { Injectable } from '@nestjs/common';
405	import { ExceptionHelper, IdempotencyKeyEntity } from '@roombook/backend-common';
406	import {
407	  BookingDto,
408	  CreateBookingMessageDto,
409	  CreateBookingResultDto,
410	  ErrorCodeEnum,
411	  ListBookingsQueryDto,
412	  PagedBookingsDto,
413	  RecordConfirmationResultDto,
414	  UpdateBookingMessageDto,
415	} from '@roombook/contract';
416	import { BookingFingerprintUtil } from './booking-fingerprint.util';
417	import { BookingTimeUtil } from './booking-time.util';
418	import { BookingRepository } from './booking.repository';
419	import { BookingValidator } from './booking.validator';
420	import { ConfirmationQueueProducer } from './confirmation-queue.producer';
421	import { IdempotentCreateOutcome, IdempotentCreateOutcomeKindEnum } from './dto/idempotent-create-outcome';
422	import { IdempotentBookingRepository } from './idempotent-booking.repository';
423	import { RoomLookupClient } from './room-lookup.client';
424	
425	@Injectable()
426	export class BookingService {
427	  constructor(
428	    private readonly bookingRepository: BookingRepository,
429	    private readonly idempotentBookingRepository: IdempotentBookingRepository,
430	    private readonly bookingValidator: BookingValidator,
431	    private readonly roomLookupClient: RoomLookupClient,
432	    private readonly confirmationQueueProducer: ConfirmationQueueProducer,
433	  ) {}
434	
435	  async createBooking(message: CreateBookingMessageDto): Promise<CreateBookingResultDto> {
436	    const { idempotencyKey, booking } = message;
437	    const startsAt = BookingTimeUtil.toDate(booking.startsAt);
438	    const endsAt = BookingTimeUtil.toDate(booking.endsAt);
439	    this.bookingValidator.assertTimeOrder(startsAt, endsAt);
440	    const requestFingerprint = BookingFingerprintUtil.of(booking);
441	    const storedKey = await this.idempotentBookingRepository.findByKey(idempotencyKey);
442	    if (storedKey) {
443	      return this.replay(storedKey, requestFingerprint);
444	    }
445	    await this.roomLookupClient.assertRoomExists(booking.roomId);
446	    const outcome = await this.idempotentBookingRepository.create({
447	      idempotencyKey,
448	      requestFingerprint,
449	      roomId: booking.roomId,
450	      title: booking.title,
451	      organizerEmail: booking.organizerEmail,
452	      startsAt,
453	      endsAt,
454	    });
455	    return this.resolveCreateOutcome(outcome, requestFingerprint);
456	  }
457	
458	  listBookings(query: ListBookingsQueryDto): Promise<PagedBookingsDto> {
459	    return this.bookingRepository.findPage(query);
460	  }
461	
462	  async findBookingById(id: string): Promise<BookingDto> {
463	    const booking = await this.bookingRepository.findById(id);
464	    return booking ?? this.raiseNotFound(id);
465	  }
466	
467	  async updateBooking(message: UpdateBookingMessageDto): Promise<BookingDto> {
468	    const { id, changes } = message;
469	    const stored = await this.findBookingById(id);
470	    const startsAt = BookingTimeUtil.toDate(changes.startsAt ?? stored.startsAt);
471	    const endsAt = BookingTimeUtil.toDate(changes.endsAt ?? stored.endsAt);
472	    this.bookingValidator.assertTimeOrder(startsAt, endsAt);
473	    const updated = await this.bookingRepository.update({ id, title: changes.title ?? stored.title, startsAt, endsAt });
474	    return updated ?? this.raiseNotFound(id);
475	  }
476	
477	  async deleteBooking(id: string): Promise<boolean> {
478	    const deleted = await this.bookingRepository.delete(id);
479	    return deleted || this.raiseNotFound(id);
480	  }
481	
482	  recordConfirmationResult(outcome: RecordConfirmationResultDto): Promise<boolean> {
483	    return this.bookingRepository.recordConfirmation(outcome);
484	  }
485	
486	  private async resolveCreateOutcome(
487	    outcome: IdempotentCreateOutcome,
488	    requestFingerprint: string,
489	  ): Promise<CreateBookingResultDto> {
490	    switch (outcome.kind) {
491	      case IdempotentCreateOutcomeKindEnum.CREATED:
492	        await this.confirmationQueueProducer.enqueue(outcome.booking.id);
493	        return { booking: outcome.booking, replayed: false };
494	      case IdempotentCreateOutcomeKindEnum.EXISTING:
495	        return this.replay(outcome.storedKey, requestFingerprint);
496	      case IdempotentCreateOutcomeKindEnum.IN_PROGRESS:
497	        return ExceptionHelper.conflict(
498	          ErrorCodeEnum.IDEMPOTENCY_IN_PROGRESS,
499	          'A request with this Idempotency-Key is still being processed',
500	        );
501	    }
502	  }
503	
504	  private replay(storedKey: IdempotencyKeyEntity, requestFingerprint: string): CreateBookingResultDto {
505	    if (storedKey.requestFingerprint !== requestFingerprint) {
506	      ExceptionHelper.unprocessable(
507	        ErrorCodeEnum.IDEMPOTENCY_KEY_REUSED,
508	        'This Idempotency-Key was already used with a different body',
509	      );
510	    }
511	    return { booking: storedKey.responseBody, replayed: true };
512	  }
513	
514	  private raiseNotFound(id: string): never {
515	    return ExceptionHelper.notFound(ErrorCodeEnum.BOOKING_NOT_FOUND, `Booking ${id} was not found`);
516	  }
517	}
