      updated,
    );
    expect(bookingRepository.update).toHaveBeenCalledWith({
      id: BOOKING_ID,
      title: 'Retro',
      startsAt: new Date('2030-01-01T10:00:00.000Z'),
      endsAt: new Date('2030-01-01T11:00:00.000Z'),
