  it('updates both times, reading an offset and a zone-less value as UTC instants', async () => {
    bookingRepository.update.mockResolvedValue(bookingDto());

    await service.updateBooking({
      id: BOOKING_ID,
      changes: { startsAt: '2030-02-01T10:00:00+02:00', endsAt: '2030-02-01T09:00:00' },
    });

    expect(bookingRepository.update).toHaveBeenCalledWith({
      id: BOOKING_ID,
      title: 'Planning',
      startsAt: new Date('2030-02-01T08:00:00.000Z'),
      endsAt: new Date('2030-02-01T09:00:00.000Z'),
    });
  });

  it('keeps every stored value for an empty change set', async () => {
    bookingRepository.update.mockResolvedValue(bookingDto());

    await expect(service.updateBooking({ id: BOOKING_ID, changes: {} })).resolves.toEqual(bookingDto());
    expect(bookingRepository.update).toHaveBeenCalledWith({
      id: BOOKING_ID,
      title: 'Planning',
      startsAt: new Date('2030-01-01T10:00:00.000Z'),
      endsAt: new Date('2030-01-01T11:00:00.000Z'),
    });
  });

  it.each([
    ['moves startsAt past the stored endsAt', { startsAt: '2030-01-01T12:00:00Z' }],
    ['moves endsAt onto the stored startsAt', { endsAt: '2030-01-01T10:00:00Z' }],
    ['carries a time that is not an instant', { startsAt: '2030-W01-1' }],
  ])('raises 400 BAD_REQUEST.VALIDATION and stores nothing when an update %s', async (_case, changes) => {
    expect(await rpcErrorOf(() => service.updateBooking({ id: BOOKING_ID, changes }))).toEqual(
      expect.objectContaining({ statusCode: 400, errorCode: ErrorCodeEnum.VALIDATION }),
    );
    expect(bookingRepository.update).not.toHaveBeenCalled();
  });

  it('raises 404 NOT_FOUND.BOOKING when the updated id is unknown', async () => {
    bookingRepository.findById.mockResolvedValue(null);

    expect(await rpcErrorOf(() => service.updateBooking({ id: BOOKING_ID, changes: { title: 'x' } }))).toEqual(
      notFound,
    );
    expect(bookingRepository.update).not.toHaveBeenCalled();
  });

  it('raises 404 NOT_FOUND.BOOKING when the booking is deleted while it is updated', async () => {
    bookingRepository.update.mockResolvedValue(null);

    expect(await rpcErrorOf(() => service.updateBooking({ id: BOOKING_ID, changes: { title: 'x' } }))).toEqual(
      notFound,
    );
  });

  it('deletes a booking', async () => {
    bookingRepository.delete.mockResolvedValue(true);

    await expect(service.deleteBooking(BOOKING_ID)).resolves.toBe(true);
    expect(bookingRepository.delete).toHaveBeenCalledWith(BOOKING_ID);
  });

  it('raises 404 NOT_FOUND.BOOKING when the deleted id is unknown', async () => {
    bookingRepository.delete.mockResolvedValue(false);

    expect(await rpcErrorOf(() => service.deleteBooking(BOOKING_ID))).toEqual(notFound);
  });

  it('records a confirmation outcome on the booking', async () => {
    const outcome = { bookingId: BOOKING_ID, status: ConfirmationStatusEnum.SENT, attempts: 1 };
    bookingRepository.recordConfirmation.mockResolvedValue(true);

    await expect(service.recordConfirmationResult(outcome)).resolves.toBe(true);
    expect(bookingRepository.recordConfirmation).toHaveBeenCalledWith(outcome);
  });

  it('answers without error when the outcome is for an unknown or already final booking', async () => {
    bookingRepository.recordConfirmation.mockResolvedValue(false);

    await expect(
      service.recordConfirmationResult({ bookingId: BOOKING_ID, status: ConfirmationStatusEnum.PENDING, attempts: 1 }),
    ).resolves.toBe(false);
  });
});

