798	export const createBooking = async (booking: CreateBookingDto, idempotencyKey: string): Promise<BookingDto> => {
799	  const { data } = await apiClient.post<BookingDto>(BOOKINGS_PATH, booking, {
800	    headers: { [IDEMPOTENCY_KEY_HEADER]: idempotencyKey },
801	  });
802	  return data;
