import { Injectable } from '@nestjs/common';
import { ExceptionHelper, IdempotencyKeyEntity } from '@roombook/backend-common';
import {
  BookingDto,
  CreateBookingMessageDto,
  CreateBookingResultDto,
  ErrorCodeEnum,
