import { randomUUID } from 'node:crypto';

const base = `http://localhost:${process.argv[2]}/api`;
const OVERLAP = 'CONFLICT.BOOKING_OVERLAP';
let failures = 0;

const check = (label, ok, detail = '') => {
  if (!ok) failures += 1;
  console.log(`${ok ? 'PASS' : 'FAIL'}  ${label}${ok ? '' : `  -> ${detail}`}`);
};

const call = async (method, path, body, key) => {
  const response = await fetch(`${base}${path}`, {
    method,
    headers: { 'Content-Type': 'application/json', ...(key ? { 'Idempotency-Key': key } : {}) },
    body: body ? JSON.stringify(body) : undefined,
  });
  const text = await response.text();
  return {
    status: response.status,
    replayed: response.headers.get('Idempotency-Replayed'),
    body: text ? JSON.parse(text) : null,
  };
};

const span = (roomId, from, to, day = '2031-03-01') => ({
  roomId,
  title: 'Live check',
  organizerEmail: 'qa.user+overlap@example.com',
  startsAt: `${day}T${from}:00Z`,
  endsAt: `${day}T${to}:00Z`,
});
const create = (roomId, from, to, key = randomUUID(), day) => call('POST', '/bookings', span(roomId, from, to, day), key);
const isOverlap = (r) => r.status === 409 && r.body.errorCode === OVERLAP && r.body.message.length > 0 && !r.replayed;
const describe = (r) => `${r.status} ${r.body?.errorCode ?? ''} replayed=${r.replayed}`;
const total = async (roomId) => (await call('GET', `/bookings?roomId=${roomId}`)).body.total;

const roomsAnswer = (await call('GET', '/rooms?limit=20')).body;
const rooms = (roomsAnswer.items ?? roomsAnswer).map((room) => room.id);
const [a, b, c, ...raceRooms] = rooms;

console.log('--- 7.3 bookings-api');
const first = await create(a, '10:00', '11:00');
check('first create 201', first.status === 201, describe(first));
for (const [label, from, to] of [
  ['identical span', '10:00', '11:00'],
  ['overlap at the start', '09:30', '10:30'],
  ['overlap at the end', '10:30', '11:30'],
  ['inside', '10:15', '10:45'],
  ['containing', '09:00', '12:00'],
]) {
  const r = await create(a, from, to);
  check(`${label} -> 409 overlap`, isOverlap(r), describe(r));
}
check('room still has one booking', (await total(a)) === 1);
const after = await create(a, '11:00', '12:00');
check('adjacent after -> 201', after.status === 201, describe(after));
const before = await create(a, '09:00', '10:00');
check('adjacent before -> 201', before.status === 201, describe(before));
const otherRoom = await create(b, '10:00', '11:00');
check('same span in another room -> 201', otherRoom.status === 201, describe(otherRoom));
const unknownRoom = await create(randomUUID(), '10:00', '11:00');
check('unknown room -> 404 NOT_FOUND.ROOM', unknownRoom.status === 404 && unknownRoom.body.errorCode === 'NOT_FOUND.ROOM');

const later = await create(a, '13:00', '14:00');
const moved = await call('PATCH', `/bookings/${later.body.id}`, { startsAt: '2031-03-01T10:30:00Z' });
check('update onto another booking -> 409 overlap', isOverlap(moved), describe(moved));
const reread = (await call('GET', `/bookings/${later.body.id}`)).body;
check('rejected update left the booking unchanged', reread.startsAt === later.body.startsAt && reread.endsAt === later.body.endsAt);
const extended = await call('PATCH', `/bookings/${first.body.id}`, { endsAt: '2031-03-01T11:30:00Z' });
check('update extended into another booking -> 409 overlap', isOverlap(extended), describe(extended));
const toEdge = await call('PATCH', `/bookings/${after.body.id}`, { endsAt: '2031-03-01T13:00:00Z' });
check('update up to the edge of another booking -> 200', toEdge.status === 200 && toEdge.body.endsAt.startsWith('2031-03-01T13:00'));
const titleOnly = await call('PATCH', `/bookings/${later.body.id}`, { title: 'Retro' });
check('title-only update -> 200', titleOnly.status === 200 && titleOnly.body.title === 'Retro', describe(titleOnly));
const shortened = await call('PATCH', `/bookings/${later.body.id}`, {
  startsAt: '2031-03-01T13:15:00Z',
  endsAt: '2031-03-01T13:45:00Z',
});
check('shortened inside its own span -> 200', shortened.status === 200, describe(shortened));
const shifted = await call('PATCH', `/bookings/${later.body.id}`, {
  startsAt: '2031-03-01T13:30:00Z',
  endsAt: '2031-03-01T14:30:00Z',
});
check('moved onto only its own old span -> 200', shifted.status === 200, describe(shifted));
const unknownBooking = await call('PATCH', `/bookings/${randomUUID()}`, { startsAt: '2031-03-01T10:30:00Z' });
check('unknown booking -> 404 NOT_FOUND.BOOKING', unknownBooking.status === 404 && unknownBooking.body.errorCode === 'NOT_FOUND.BOOKING');
const removed = await call('DELETE', `/bookings/${before.body.id}`);
const refilled = await create(a, '09:00', '10:00');
check('span freed by a delete -> 201', removed.status === 204 && refilled.status === 201, describe(refilled));

console.log('--- 7.4 booking-idempotency');
const holderKey = randomUUID();
const holder = await create(c, '10:00', '11:00', holderKey);
const rejectedKey = randomUUID();
const rejected = await create(c, '10:00', '11:00', rejectedKey);
check('rejected create -> 409 overlap, no replay header', isOverlap(rejected), describe(rejected));
const rejectedAgain = await create(c, '10:00', '11:00', rejectedKey);
check('same key repeated while overlap remains -> 409 again, not replayed', isOverlap(rejectedAgain), describe(rejectedAgain));
check('list shows no booking for the rejected creates', (await total(c)) === 1);
const replay = await create(c, '10:00', '11:00', holderKey);
check('completed create repeated -> 201 replayed', replay.status === 201 && replay.replayed === 'true' && replay.body.id === holder.body.id, describe(replay));
const reusedKey = await create(c, '10:30', '11:30', holderKey);
check('completed key with another overlapping body -> 422', reusedKey.status === 422 && reusedKey.body.errorCode === 'UNPROCESSABLE.IDEMPOTENCY_KEY_REUSED', describe(reusedKey));
await call('DELETE', `/bookings/${holder.body.id}`);
const accepted = await create(c, '10:00', '11:00', rejectedKey);
check('same key and body after the span is free -> 201, not replayed', accepted.status === 201 && !accepted.replayed, describe(accepted));
const freeSpanKey = randomUUID();
await create(c, '10:00', '11:00', freeSpanKey);
const freeSpan = await create(c, '15:00', '16:00', freeSpanKey);
check('rejected key reused for a free span -> 201, not replayed', freeSpan.status === 201 && !freeSpan.replayed, describe(freeSpan));
check('room holds exactly the two accepted bookings', (await total(c)) === 2);

console.log('--- 7.5 concurrency');
const waitForSent = async (id) => {
  for (let attempt = 0; attempt < 40; attempt += 1) {
    const { body } = await call('GET', `/bookings/${id}`);
    if (body.confirmationStatus !== 'PENDING') return body;
    await new Promise((resolve) => setTimeout(resolve, 500));
  }
  return (await call('GET', `/bookings/${id}`)).body;
};
for (const [run, roomId] of raceRooms.slice(0, 3).entries()) {
  const answers = await Promise.all(Array.from({ length: 10 }, () => create(roomId, '10:00', '11:00')));
  const created = answers.filter((r) => r.status === 201);
  const overlaps = answers.filter(isOverlap);
  const summary = answers.map((r) => r.status).join(',');
  check(`run ${run + 1}: one 201 and nine 409 overlap, no 5xx`, created.length === 1 && overlaps.length === 9, summary);
  check(`run ${run + 1}: room total is 1`, (await total(roomId)) === 1);
  const confirmed = created[0] ? await waitForSent(created[0].body.id) : {};
  check(
    `run ${run + 1}: booking reaches SENT with 1 attempt`,
    confirmed.confirmationStatus === 'SENT' && confirmed.confirmationAttempts === 1,
    `${confirmed.confirmationStatus} / ${confirmed.confirmationAttempts}`,
  );
}
const [roomX, roomY, roomZ] = raceRooms.slice(3, 6);
const twoRooms = await Promise.all([create(roomX, '10:00', '11:00'), create(roomY, '10:00', '11:00')]);
check('concurrent creates for different rooms -> both 201', twoRooms.every((r) => r.status === 201));
const mover = await create(roomZ, '08:00', '09:00');
const race = await Promise.all([
  create(roomZ, '10:00', '11:00'),
  call('PATCH', `/bookings/${mover.body.id}`, { startsAt: '2031-03-01T10:00:00Z', endsAt: '2031-03-01T11:00:00Z' }),
]);
const winners = race.filter((r) => r.status === 200 || r.status === 201).length;
check('create and update racing for one span -> one wins, one 409 overlap', winners === 1 && race.filter(isOverlap).length === 1, race.map(describe).join(' | '));

console.log(failures ? `${failures} check(s) FAILED` : 'ALL CHECKS PASSED');
process.exit(failures ? 1 : 0);

