const { randomUUID } = require('node:crypto');

const base = 'http://localhost:3110/api';
const OVERLAP = 'CONFLICT.BOOKING_OVERLAP';
const lines = [];
const failed = [];

const check = (label, ok, detail = '') => {
  if (!ok) failed.push(label);
  lines.push(`${ok ? 'PASS' : 'FAIL'}  ${label}${ok ? '' : `  -> ${detail}`}`);
};

const call = async (method, path, body, key) => {
  const response = await fetch(`${base}${path}`, {
    method,
    headers: { 'Content-Type': 'application/json', ...(key ? { 'Idempotency-Key': key } : {}) },
    body: body ? JSON.stringify(body) : undefined,
  });
  const text = await response.text();
  return {
    status: response.status,
    replayed: response.headers.get('Idempotency-Replayed'),
    body: text ? JSON.parse(text) : null,
  };
};

const span = (roomId, from, to) => ({
  roomId,
  title: 'Live check',
  organizerEmail: 'qa.user+overlap@example.com',
  startsAt: `2031-03-01T${from}:00Z`,
  endsAt: `2031-03-01T${to}:00Z`,
});
const create = (roomId, from, to, key = randomUUID()) => call('POST', '/bookings', span(roomId, from, to), key);
const isOverlap = (r) => r.status === 409 && r.body.errorCode === OVERLAP && r.body.message.length > 0 && !r.replayed;
const describeAnswer = (r) => `${r.status} ${(r.body && r.body.errorCode) || ''} replayed=${r.replayed}`;
const total = async (roomId) => (await call('GET', `/bookings?roomId=${roomId}`)).body.total;

const waitForConfirmation = async (id) => {
  for (let attempt = 0; attempt < 40; attempt += 1) {
    const { body } = await call('GET', `/bookings/${id}`);
    if (body.confirmationStatus !== 'PENDING') return body;
    await new Promise((resolve) => setTimeout(resolve, 500));
  }
  return (await call('GET', `/bookings/${id}`)).body;
};

const runApiChecks = async (a, b) => {
  lines.push('--- 7.3 bookings-api');
  const first = await create(a, '10:00', '11:00');
  check('first create 201', first.status === 201, describeAnswer(first));
  const rejections = [
    ['identical span', '10:00', '11:00'],
    ['overlap at the start', '09:30', '10:30'],
    ['overlap at the end', '10:30', '11:30'],
    ['inside', '10:15', '10:45'],
    ['containing', '09:00', '12:00'],
  ];
  for (const [label, from, to] of rejections) {
    const r = await create(a, from, to);
    check(`${label} -> 409 overlap`, isOverlap(r), describeAnswer(r));
  }
  check('room still has one booking', (await total(a)) === 1);
  const after = await create(a, '11:00', '12:00');
  check('adjacent after -> 201', after.status === 201, describeAnswer(after));
  const before = await create(a, '09:00', '10:00');
  check('adjacent before -> 201', before.status === 201, describeAnswer(before));
  const otherRoom = await create(b, '10:00', '11:00');
  check('same span in another room -> 201', otherRoom.status === 201, describeAnswer(otherRoom));
  const unknownRoom = await create(randomUUID(), '10:00', '11:00');
  check('unknown room -> 404 NOT_FOUND.ROOM', unknownRoom.status === 404 && unknownRoom.body.errorCode === 'NOT_FOUND.ROOM');

  const later = await create(a, '13:00', '14:00');
  const moved = await call('PATCH', `/bookings/${later.body.id}`, { startsAt: '2031-03-01T10:30:00Z' });
  check('update onto another booking -> 409 overlap', isOverlap(moved), describeAnswer(moved));
  const reread = (await call('GET', `/bookings/${later.body.id}`)).body;
  check(
    'rejected update left the booking unchanged',
    reread.startsAt === later.body.startsAt && reread.endsAt === later.body.endsAt,
  );
  const extended = await call('PATCH', `/bookings/${first.body.id}`, { endsAt: '2031-03-01T11:30:00Z' });
  check('update extended into another booking -> 409 overlap', isOverlap(extended), describeAnswer(extended));
  const toEdge = await call('PATCH', `/bookings/${after.body.id}`, { endsAt: '2031-03-01T13:00:00Z' });
  check(
    'update up to the edge of another booking -> 200',
    toEdge.status === 200 && toEdge.body.endsAt.startsWith('2031-03-01T13:00'),
    describeAnswer(toEdge),
  );
  const titleOnly = await call('PATCH', `/bookings/${later.body.id}`, { title: 'Retro' });
  check('title-only update -> 200', titleOnly.status === 200 && titleOnly.body.title === 'Retro', describeAnswer(titleOnly));
  const shortened = await call('PATCH', `/bookings/${later.body.id}`, {
    startsAt: '2031-03-01T13:15:00Z',
    endsAt: '2031-03-01T13:45:00Z',
  });
  check('shortened inside its own span -> 200', shortened.status === 200, describeAnswer(shortened));
  const shifted = await call('PATCH', `/bookings/${later.body.id}`, {
    startsAt: '2031-03-01T13:30:00Z',
    endsAt: '2031-03-01T14:30:00Z',
  });
  check('moved onto only its own old span -> 200', shifted.status === 200, describeAnswer(shifted));
  const unknownBooking = await call('PATCH', `/bookings/${randomUUID()}`, { startsAt: '2031-03-01T10:30:00Z' });
  check(
    'unknown booking -> 404 NOT_FOUND.BOOKING',
    unknownBooking.status === 404 && unknownBooking.body.errorCode === 'NOT_FOUND.BOOKING',
  );
  const removed = await call('DELETE', `/bookings/${before.body.id}`);
  const refilled = await create(a, '09:00', '10:00');
  check('span freed by a delete -> 201', removed.status === 204 && refilled.status === 201, describeAnswer(refilled));
};

const runIdempotencyChecks = async (c) => {
  lines.push('--- 7.4 booking-idempotency');
  const holderKey = randomUUID();
  const holder = await create(c, '10:00', '11:00', holderKey);
  const rejectedKey = randomUUID();
  const rejected = await create(c, '10:00', '11:00', rejectedKey);
  check('rejected create -> 409 overlap, no replay header', isOverlap(rejected), describeAnswer(rejected));
  const rejectedAgain = await create(c, '10:00', '11:00', rejectedKey);
  check('same key repeated while overlap remains -> 409 again, not replayed', isOverlap(rejectedAgain), describeAnswer(rejectedAgain));
  check('list shows no booking for the rejected creates', (await total(c)) === 1);
