  const sent = await waitForConfirmation(accepted.body.id);
  check('that booking gets its one confirmation', sent.confirmationStatus === 'SENT' && sent.confirmationAttempts === 1);
  const freeSpanKey = randomUUID();
  const freeSpanRejected = await create(c, '10:00', '11:00', freeSpanKey);
  const freeSpan = await create(c, '15:00', '16:00', freeSpanKey);
  check(
    'rejected key reused for a free span -> 201, not replayed',
    isOverlap(freeSpanRejected) && freeSpan.status === 201 && !freeSpan.replayed,
    describeAnswer(freeSpan),
  );
  check('room holds exactly the two accepted bookings', (await total(c)) === 2);
};

const runConcurrencyChecks = async (raceRooms) => {
  lines.push('--- 7.5 concurrency');
  for (const [run, roomId] of raceRooms.slice(0, 3).entries()) {
    const answers = await Promise.all(Array.from({ length: 10 }, () => create(roomId, '10:00', '11:00')));
    const created = answers.filter((r) => r.status === 201);
    const summary = answers.map((r) => r.status).join(',');
    check(
      `run ${run + 1}: one 201 and nine 409 overlap, no 5xx`,
